package com.strmr.tv.api

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonObject

// The player's extras: seek-preview thumbnails (`/api/video/thumbnails/...`, generated by the
// server or fetched from Seekr) and intro / recap / credits ranges (`/api/video/segments`).

@Serializable
data class VideoThumbnailStatus(
    val key: String? = null,
    /** `pending`, `generating`, `ready`, `failed` or `disabled`. */
    val status: String = "",
    val thumbnails: List<Item>? = null,
) {
    @Serializable
    data class Item(val timeSec: Double, val url: String)
}

/** What the start request tells the server about the stream (Seekr lookup, HDR tone mapping). */
data class ThumbnailStartOptions(
    val seekrOnly: Boolean,
    val imdbId: String?,
    val tmdbId: String?,
    /** `movie` or `episode`. */
    val mediaType: String,
    val season: Int?,
    val episode: Int?,
    val hdr: Boolean,
    val dolbyVision: Boolean,
)

suspend fun ApiClient.videoThumbnailsStatus(path: String): VideoThumbnailStatus =
    thumbnails("GET", "/api/video/thumbnails/status", "path=${segment(path)}")

suspend fun ApiClient.startVideoThumbnails(path: String, durationSec: Double, options: ThumbnailStartOptions): VideoThumbnailStatus {
    val items = buildList {
        add("path" to path)
        add("duration" to "%.2f".format(java.util.Locale.ROOT, durationSec))
        add("interval" to "60")
        if (options.hdr) add("hdr" to "1")
        if (options.dolbyVision) add("dv" to "1")
        if (options.seekrOnly) add("seekrOnly" to "1")
        options.imdbId?.let { add("imdbId" to it) }
        options.tmdbId?.let { add("tmdbId" to it) }
        add("mediaType" to options.mediaType)
        options.season?.let { add("season" to it.toString()) }
        options.episode?.let { add("episode" to it.toString()) }
    }
    return thumbnails("POST", "/api/video/thumbnails/start", items.joinToString("&") { (k, v) -> "${segment(k)}=${segment(v)}" })
}

private suspend fun ApiClient.thumbnails(method: String, path: String, query: String): VideoThumbnailStatus =
    json.decodeFromString(sendRaw(method, path, promptOnLock = false, timeoutMs = 60_000, encodedQuery = query))

/** Absolute URL of a listed thumbnail (server-relative `/api/...`); auth rides in [mediaHeaders]. */
fun ApiClient.thumbnailImageUrl(raw: String): String? {
    if (raw.startsWith("http://") || raw.startsWith("https://")) return raw
    val path = raw.substringBefore('?')
    return if (path.startsWith("/")) url(path).toString() else null
}

@Serializable
private data class ServerSettings(val playback: Playback? = null) {
    @Serializable
    data class Playback(val thumbnails: Thumbnails? = null)

    @Serializable
    data class Thumbnails(val enabled: Boolean? = null)
}

/** Whether the server admin turned seek-preview thumbnails on (`playback.thumbnails.enabled`). */
suspend fun ApiClient.previewThumbnailsEnabled(): Boolean =
    runCatching { send<ServerSettings>("GET", "/api/settings", promptOnLock = false, timeoutMs = 10_000) }
        .getOrNull()?.playback?.thumbnails?.enabled ?: false

/** One skippable range, in seconds. */
@Serializable
data class SkipSegment(
    /** `intro`, `recap`, `outro` or `preview`. */
    val type: String,
    val start: Double,
    val end: Double,
)

@Serializable
private data class SkipSegmentsResponse(val segments: List<SkipSegment>? = null)

suspend fun ApiClient.skipSegments(body: JsonObject): List<SkipSegment> =
    send<SkipSegmentsResponse>("POST", "/api/video/segments", body = body, promptOnLock = false).segments.orEmpty()
